INSERT INTO templates (id, version, json, active) VALUES ('text.process', 1, '{"id": "text.process", "title": "Text action", "description": "Runs a preset prompt (rewrite, translate, explain, reply...) over the user''s text.", "system": "You are a text processing assistant. Respond ONLY with the processed result, no preamble, explanation, or surrounding quotation marks.", "user_template": "{{content}}", "variables": ["content"], "model": null, "max_tokens": 1024, "version": 1}', 1);
INSERT INTO templates (id, version, json, active) VALUES ('email.reply', 1, '{"id": "email.reply", "title": "Email reply", "description": "Drafts an email reply from the original email and the user''s instructions.", "system": "You are an email writing assistant. Write ONLY the reply email content, no preamble. Start with the greeting and end with a sign-off. Professional yet friendly unless told otherwise.", "user_template": "{{content}}", "variables": ["content"], "model": null, "max_tokens": 1024, "version": 1}', 1);
INSERT INTO templates (id, version, json, active) VALUES ('ask', 1, '{"id": "ask", "title": "Ask", "description": "Answers a free-form question.", "system": "You are a helpful assistant. Answer the user''s request directly and clearly.", "user_template": "{{content}}", "variables": ["content"], "model": null, "max_tokens": 4096, "version": 1}', 1);
